// Jupiter GitHub kit: renders banners, dividers, tiles, badges and the social preview as standalone SVG strings.
// Pure and dependency-free (browser + Node), so the admin Targets page can preview it live. The theme is the slice of the tokens in
// theme.json (generated by @belikh/jupiter-tokens: colours per scheme, fonts, radius), so a token change changes every file.
//
// Built for how GitHub shows SVG: via <img>, so no scripts, no external fonts or links. Fonts are base64 subsets embedded with @font-face;
// the flowing line and spots animate with CSS and stop under prefers-reduced-motion. Light and dark are separate files, switched
// in Markdown with <picture><source media="(prefers-color-scheme: dark)">.
import { FONT_DATA } from "./fonts.mjs";
import { LOGO } from "./logo.mjs";

export const SCHEMES = ["light", "dark"];
export const STATUSES = ["ok", "warn", "danger", "info", "accent", "neutral"];

const n = (v) => Math.round(v * 100) / 100;
/** XML-escape text and drop control characters. */
export const esc = (s) => String(s ?? "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const firstFamily = (stack) => (stack.split(",")[0] ?? "").trim().replace(/^["']|["']$/g, "");

function colors(theme, scheme) {
  const c = theme.color?.[scheme];
  if (!c) throw new Error(`unknown scheme "${scheme}" (use light or dark)`);
  return c;
}

/** Status colours: text/dot colour and soft background. accent and neutral borrow the accent and surface roles. */
export function statusColors(theme, scheme, status = "neutral") {
  const c = colors(theme, scheme);
  if (status === "ok" || status === "warn" || status === "danger" || status === "info") return { fg: c[status], bg: c[`${status}Bg`] };
  if (status === "accent") return { fg: c.accent, bg: c.accent, on: c.onAccent, solid: true };
  if (status === "neutral") return { fg: c.textMuted, bg: c.surfaceRaised };
  throw new Error(`unknown status "${status}" (use ${STATUSES.join(", ")})`);
}

function fontCss(theme, used) {
  const sans = theme.font.sans, mono = theme.font.mono;
  const face = (k) => `@font-face{font-family:"${FONT_DATA[k].family}";font-weight:${FONT_DATA[k].weight};font-style:normal;src:url(data:font/woff2;base64,${FONT_DATA[k].data}) format("woff2")}`;
  return [...used.map(face),
    `.t{font-family:${sans};font-weight:800}`,
    `.b{font-family:${sans};font-weight:400}`,
    `.m{font-family:${mono};font-weight:500}`].join("\n");
}

/** Shrink a font size so `text` fits `maxW` (average glyph width = `k` em), never below `min`. */
const fit = (text, size, maxW, k, min) => Math.max(min, Math.min(size, maxW / Math.max(1, [...String(text)].length * k)));

/** Smooth path through points (Catmull-Rom to cubic Bezier): one continuous, flowing stroke. */
function flowPath(pts) {
  let d = `M${n(pts[0][0])} ${n(pts[0][1])}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
    d += ` C${n(p1[0] + (p2[0] - p0[0]) / 6)} ${n(p1[1] + (p2[1] - p0[1]) / 6)} ${n(p2[0] - (p3[0] - p1[0]) / 6)} ${n(p2[1] - (p3[1] - p1[1]) / 6)} ${n(p2[0])} ${n(p2[1])}`;
  }
  return d;
}

const MOTION = `@keyframes flow{to{stroke-dashoffset:-240}}
@keyframes pulse{0%,100%{opacity:.18}50%{opacity:.5}}
.flow{animation:flow 9s linear infinite}
.halo{animation:pulse 4s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.flow,.halo{animation:none}}`;

function svg(w, h, theme, scheme, { title, desc, fonts, css = "", body }) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="t d">
<!-- Generated from jupiter.tokens.json (${esc(theme.name)} ${esc(theme.version)}), ${scheme} scheme. Do not edit by hand. -->
<title id="t">${esc(title)}</title><desc id="d">${esc(desc ?? title)}</desc>
<style>
${fontCss(theme, fonts)}
${css}
</style>
${body}
</svg>
`;
}

/** The flowing line with its status spots: faint full path, animated accent dashes, spots with halos. */
function flow(c, pts, spots, width = 2) {
  const d = flowPath(pts);
  const dots = spots.map(([i, role], k) => {
    const [x, y] = pts[i];
    return `<circle class="halo" style="animation-delay:${k * 0.9}s" cx="${n(x)}" cy="${n(y)}" r="${width * 6}" fill="${c[role]}"/><circle cx="${n(x)}" cy="${n(y)}" r="${width * 2.4}" fill="${c[role]}" stroke="${c.bg}" stroke-width="${width}"/>`;
  }).join("");
  return `<path d="${d}" fill="none" stroke="${c.border}" stroke-width="${width}" stroke-linecap="round"/>
<path class="flow" d="${d}" fill="none" stroke="${c.accent}" stroke-width="${width}" stroke-linecap="round" stroke-dasharray="3 21"/>
${dots}`;
}

/** The Jupiter logo (packages/graphics/logo), nested at x,y with the given width. */
const logo = (scheme, x, y, w) => { const L = LOGO[scheme]; return `<svg x="${x}" y="${y}" width="${n(w)}" height="${n((w * L.h) / L.w)}" viewBox="${L.viewBox}">${L.inner}</svg>`; };

const rnd = (theme) => n(theme.radius?.md ?? 6);

/** Wide README banner, 1280x320. */
export function renderBanner(theme, scheme, { title = "Project name", subtitle = "One line about what it does", eyebrow = "jupiter", logo: useLogo = false } = {}) {
  const c = colors(theme, scheme), r = rnd(theme);
  const ts = n(fit(title, 60, 600, 0.58, 30)), ss = n(fit(subtitle, 22, 600, 0.5, 14));
  const pts = [[690, 236], [780, 118], [870, 206], [960, 96], [1050, 196], [1140, 108], [1224, 176]];
  return svg(1280, 320, theme, scheme, {
    title: `${title}: ${subtitle}`, fonts: ["title", "body", "mono"], css: `.e{font-size:14px;letter-spacing:.16em;fill:${c.textMuted}}.h{fill:${c.text}}.s{fill:${c.textMuted}}\n${MOTION}`,
    body: `<rect x=".5" y=".5" width="1279" height="319" rx="${r}" fill="${c.bg}" stroke="${c.border}"/>
<rect x="64" y="82" width="4" height="150" fill="${c.accent}"/>
${useLogo ? logo(scheme, 92, 64, 440) : `<text class="m e" x="92" y="100">${esc(String(eyebrow).toUpperCase())}</text>
<text class="t h" x="90" y="${n(166 + (60 - ts) * 0.3)}" font-size="${ts}">${esc(title)}</text>`}
<text class="b s" x="92" y="226" font-size="${ss}">${esc(subtitle)}</text>
<path d="M64 272H640" stroke="${c.border}" stroke-width="1"/><path d="M64 266v12M640 266v12" stroke="${c.accent}" stroke-width="2"/>
${flow(c, pts, [[1, "ok"], [3, "info"], [5, "warn"], [6, "accent"]])}`,
  });
}

/** Section divider, 1280x24: a hairline rule with one pulsing spot. */
export function renderDivider(theme, scheme) {
  const c = colors(theme, scheme);
  return svg(1280, 24, theme, scheme, {
    title: "Divider", fonts: [], css: MOTION,
    body: `<path d="M0 12H1280" stroke="${c.border}" stroke-width="1"/>
<path class="flow" d="M0 12H1280" stroke="${c.accent}" stroke-width="1" stroke-dasharray="2 22"/>
<rect x="608" y="4" width="64" height="16" fill="${c.bg}"/>
<circle class="halo" cx="640" cy="12" r="9" fill="${c.accent}"/><circle cx="640" cy="12" r="4" fill="${c.accent}"/>
<circle cx="618" cy="12" r="2" fill="${c.border}"/><circle cx="662" cy="12" r="2" fill="${c.border}"/>`,
  });
}

/** Stat / status tile, 280x104: label, big value, status spot. */
export function renderTile(theme, scheme, { label = "Build", value = "passing", status = "ok" } = {}) {
  const c = colors(theme, scheme), r = rnd(theme), st = statusColors(theme, scheme, status);
  const spot = st.solid ? c.accent : st.fg;
  const vs = n(fit(value, 38, 200, 0.58, 16));
  return svg(280, 104, theme, scheme, {
    title: `${label}: ${value}`, desc: `${label}: ${value} (${status})`, fonts: ["title", "mono"],
    css: `.l{font-size:12px;letter-spacing:.14em;fill:${c.textMuted}}.v{fill:${c.text}}\n${MOTION}`,
    body: `<rect x=".5" y=".5" width="279" height="103" rx="${r}" fill="${c.surface}" stroke="${c.border}"/>
<rect x="0" y="0" width="4" height="104" fill="${spot}"/>
<text class="m l" x="24" y="34">${esc(String(label).toUpperCase())}</text>
<text class="t v" x="23" y="${n(80 - (38 - vs) * 0.15)}" font-size="${vs}">${esc(value)}</text>
<circle class="halo" cx="248" cy="30" r="9" fill="${spot}"/><circle cx="248" cy="30" r="4.5" fill="${spot}"/>`,
  });
}

/** Two-part badge (label | value), 20px tall, sized from the monospace advance (0.6em). */
export function renderBadge(theme, scheme, { label = "status", value = "ok", status = "neutral" } = {}) {
  const c = colors(theme, scheme), r = n(theme.radius?.sm ?? 2), st = statusColors(theme, scheme, status);
  const fs = 11, adv = fs * 0.6, pad = 8, H = 20;
  const lw = Math.round([...String(label)].length * adv + pad * 2), vw = Math.round([...String(value)].length * adv + pad * 2), W = lw + vw;
  const vfg = st.solid ? st.on : st.fg;
  return svg(W, H, theme, scheme, {
    title: `${label}: ${value}`, fonts: ["mono"], css: `.x{font-size:${fs}px}`,
    body: `<clipPath id="c"><rect width="${W}" height="${H}" rx="${r}"/></clipPath>
<g clip-path="url(#c)"><rect width="${lw}" height="${H}" fill="${c.surface}"/><rect x="${lw}" width="${vw}" height="${H}" fill="${st.bg}"/></g>
<rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="${r}" fill="none" stroke="${c.border}"/>
<text class="m x" x="${pad}" y="14" fill="${c.textMuted}">${esc(label)}</text>
<text class="m x" x="${lw + pad}" y="14" fill="${vfg}">${esc(value)}</text>`,
  });
}

/** Repository social preview, 1280x640 (GitHub shows 2:1; keep text 80px inside the edge). */
export function renderSocial(theme, scheme, { title = "Project name", subtitle = "One line about what it does", eyebrow = "jupiter", footer = "", logo: useLogo = false } = {}) {
  const c = colors(theme, scheme), r = rnd(theme);
  const ts = n(useLogo ? 104 : fit(title, 104, 1080, 0.58, 48)), ss = n(fit(subtitle, 36, 1080, 0.5, 20));
  const pts = [[80, 520], [230, 452], [380, 532], [530, 440], [680, 516], [830, 446], [980, 524], [1130, 456], [1200, 490]];
  return svg(1280, 640, theme, scheme, {
    title: `${title}: ${subtitle}`, fonts: ["title", "body", "mono"], css: `.e{font-size:20px;letter-spacing:.18em;fill:${c.textMuted}}.h{fill:${c.text}}.s{fill:${c.textMuted}}.f{font-size:20px;fill:${c.textMuted}}\n${MOTION}`,
    body: `<rect width="1280" height="640" fill="${c.bg}"/>
<rect x="24.5" y="24.5" width="1231" height="591" rx="${r}" fill="none" stroke="${c.border}"/>
<rect x="80" y="86" width="6" height="${n(useLogo ? (640 * LOGO[scheme].h) / LOGO[scheme].w + ss * 1.7 + 24 : ts * 0.95 + ss * 1.5 + 60)}" fill="${c.accent}"/>
${useLogo ? logo(scheme, 112, 96, 640) : `<text class="m e" x="112" y="108">${esc(String(eyebrow).toUpperCase())}</text>
<text class="t h" x="108" y="${n(130 + ts * 0.95)}" font-size="${ts}">${esc(title)}</text>`}
<text class="b s" x="112" y="${n(useLogo ? 96 + (640 * LOGO[scheme].h) / LOGO[scheme].w + ss * 1.7 : 130 + ts * 0.95 + ss * 1.5)}" font-size="${ss}">${esc(subtitle)}</text>
${flow(c, pts, [[1, "ok"], [3, "info"], [5, "warn"], [7, "accent"]], 3)}
<text class="m f" x="80" y="590">${esc(footer)}</text>`,
  });
}

/** Markdown table of the palette with GitHub hex colour chips (`#rrggbb` renders a swatch). */
export function paletteMarkdown(theme) {
  const roles = Object.keys(theme.color.light);
  return `| Role | Light | Dark |\n| --- | --- | --- |\n${roles.map((k) => `| ${k} | \`${theme.color.light[k]}\` | \`${theme.color.dark[k]}\` |`).join("\n")}\n`;
}

export const slug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "x";
export { firstFamily };
